INSERT INTO context.skill_files (
    skill_id,
    relative_path,
    object_id,
    contents
)
SELECT
    skill.id,
    files.relative_path,
    NULL::INT,
    files.contents
FROM skill
CROSS JOIN files
ON CONFLICT (skill_id, relative_path)
DO UPDATE SET
    object_id = NULL,
    contents = EXCLUDED.contents;


-- migrate:down
WITH skill AS (
    SELECT id
    FROM context.skills
    WHERE is_system = true
    AND name = 'presentation-builder'
)
DELETE FROM context.skill_files sf
USING skill
WHERE sf.skill_id = skill.id
AND sf.relative_path IN (
    'SKILL.md',
    'bin/build-reveal-canvas.sh',
    'reveal/reveal.js',
    'reveal/reset.css',
    'reveal/reveal.css',
    'reveal/theme/serif.css',
    'LICENSE.reveal.js'
);

UPDATE context.skills
SET description = 'Create slide decks and presentation-style visual artifacts as generated HTML canvas files.'
WHERE is_system = true
AND name = 'presentation-builder';
